"""Exact pinned guide-worker lifetime patch; no changes to guides, costs or iteration strategy."""
import hashlib
UPSTREAM_SHA256='122e84ca0906d7e53d4e5f4c7216a72e55f085f1a62b0848df06fc9eafd2e3af'
DERIVED_SHA256='393bbfd15596cddfdbc3bb4d87a3055449596d5646945b89a4cc6526a32ac8b0'
OLD='  std::vector<std::vector<std::unique_ptr<FlexDRWorker>>> workers_batches(\n      route_boxes_batches.size());\n  iter_prog.total_num_workers = 0;\n  for (int batch_id = 0; batch_id < route_boxes_batches.size(); batch_id++) {\n    auto& batch = route_boxes_batches[batch_id];\n    for (const auto worker_id : batch) {\n      for (auto route_box : boxes_set[worker_id]) {\n        workers_batches[batch_id].emplace_back(\n            createWorker(0, 0, args, route_box));\n        workers_batches[batch_id].back()->setWorkerId(worker_id);\n        iter_prog.total_num_workers++;\n      }\n    }\n  }\n  bool changed = false;\n  omp_set_num_threads(router_cfg_->MAX_THREADS);\n  for (auto& batch : workers_batches) {\n    processWorkersBatch(batch, iter_prog);\n    std::map<int, FlexDRWorker*>\n        worker_best_result;  // holds the best worker in results\n    for (auto& worker : batch) {\n      const int worker_id = worker->getWorkerId();\n      if (worker_best_result.find(worker_id) == worker_best_result.end()\n          || worker->getBestNumMarkers()\n                 < worker_best_result[worker_id]->getBestNumMarkers()) {\n        worker_best_result[worker_id] = worker.get();\n      }\n    }\n    for (auto [_, worker] : worker_best_result) {\n      changed\n          |= (worker->end(getDesign())\n              && worker->getBestNumMarkers() != worker->getInitNumMarkers());\n    }\n    batch.clear();\n  }\n'
NEW='  // NSSOC: bound live guide worker state without changing the guide boxes,\n  // independent batch order, search arguments, or original iteration schedule.\n  constexpr size_t guide_worker_limit = 1;\n  iter_prog.total_num_workers = 0;\n  for (const auto& independent_batch : route_boxes_batches) {\n    for (const auto worker_id : independent_batch) {\n      iter_prog.total_num_workers += boxes_set[worker_id].size();\n    }\n  }\n  bool changed = false;\n  omp_set_num_threads(router_cfg_->MAX_THREADS);\n  std::vector<std::unique_ptr<FlexDRWorker>> batch;\n  batch.reserve(guide_worker_limit);\n  size_t processed_workers = 0;\n  auto finish_batch = [&]() {\n    if (batch.empty()) {\n      return;\n    }\n    logger_->report("NSSOC_GUIDE_WORKER_BATCH size={} limit={}",\n                    batch.size(),\n                    guide_worker_limit);\n    processWorkersBatch(batch, iter_prog);\n    std::map<int, FlexDRWorker*> worker_best_result;\n    for (auto& worker : batch) {\n      const int worker_id = worker->getWorkerId();\n      if (worker_best_result.find(worker_id) == worker_best_result.end()\n          || worker->getBestNumMarkers()\n                 < worker_best_result[worker_id]->getBestNumMarkers()) {\n        worker_best_result[worker_id] = worker.get();\n      }\n    }\n    for (auto [_, worker] : worker_best_result) {\n      changed\n          |= (worker->end(getDesign())\n              && worker->getBestNumMarkers() != worker->getInitNumMarkers());\n    }\n    processed_workers += batch.size();\n    batch.clear();\n  };\n  for (const auto& independent_batch : route_boxes_batches) {\n    for (const auto worker_id : independent_batch) {\n      // guideTilesFlow creates one box per worker ID. Keep the complete box\n      // group in one chunk so best-result selection is not split.\n      const auto& route_boxes = boxes_set[worker_id];\n      if (route_boxes.size() != 1) {\n        logger_->error(utl::DRT, 10000,\n                       "NSSOC guide batch requires exactly one box per worker");\n      }\n      if (batch.size() + route_boxes.size() > guide_worker_limit) {\n        finish_batch();\n      }\n      for (const auto& route_box : route_boxes) {\n        batch.emplace_back(createWorker(0, 0, args, route_box));\n        batch.back()->setWorkerId(worker_id);\n      }\n    }\n    finish_batch();\n  }\n  if (processed_workers != static_cast<size_t>(iter_prog.total_num_workers)) {\n    logger_->error(utl::DRT, 9998, "NSSOC guide worker accounting mismatch");\n  }\n'

def derive(raw):
    if hashlib.sha256(raw).hexdigest()!=UPSTREAM_SHA256:raise ValueError("exact upstream FlexDR source")
    text=raw.decode("utf-8")
    if text.count(OLD)!=1:raise ValueError("exact unique guide worker lifetime section")
    result=text.replace(OLD,NEW,1).encode()
    if hashlib.sha256(result).hexdigest()!=DERIVED_SHA256:raise ValueError("exact derived FlexDR source")
    if result.decode().replace(NEW,OLD,1).encode()!=raw:raise ValueError("exact source reversal")
    return result
